function main(): void {
  try { throw new Error("boom"); } catch (e: any) {
    console.log("stack" in e, "message" in e, "zzz" in e);
    delete e.stack;
    console.log(e.stack, "stack" in e, Object.getOwnPropertyNames(e));
  }
  const f: any = new Error("x");
  delete f.message;
  console.log(f.message === "", String(f));
}
